"""Core in-memory table container used across the :mod:`tabular` package."""

from __future__ import annotations

from typing import Any, Callable, Iterator, Sequence


class Table:
    """A simple, dependency-free columnar table.

    Rows are stored as lists aligned with :attr:`columns`. Cells are expected
    to be ``None`` (missing) or a scalar value (``str``, ``int``, ``float``,
    ``bool``).
    """

    def __init__(
        self,
        columns: Sequence[str],
        rows: Sequence[Sequence[Any]] | None = None,
    ) -> None:
        self.columns: list[str] = list(columns)
        if len(set(self.columns)) != len(self.columns):
            raise ValueError("column names must be unique")
        self.rows: list[list[Any]] = []
        for row in rows or []:
            self._append(list(row))

    # -- construction helpers -------------------------------------------------

    def _append(self, row: list[Any]) -> None:
        if len(row) != len(self.columns):
            raise ValueError(
                f"row has {len(row)} values, expected {len(self.columns)}"
            )
        self.rows.append(row)

    def copy(self) -> "Table":
        """Return a deep-enough copy (new row lists, shared cell values)."""
        return Table(self.columns, [list(row) for row in self.rows])

    # -- container protocol ---------------------------------------------------

    def __len__(self) -> int:
        return len(self.rows)

    def __iter__(self) -> Iterator[dict[str, Any]]:
        return iter(self.to_dicts())

    def __getitem__(self, key: int | str) -> Any:
        if isinstance(key, int):
            return self.to_dicts()[key]
        return self.column(key)

    def __eq__(self, other: object) -> bool:
        if not isinstance(other, Table):
            return NotImplemented
        return self.columns == other.columns and self.rows == other.rows

    def __repr__(self) -> str:
        return f"Table(columns={self.columns!r}, rows={len(self.rows)})"

    # -- column access --------------------------------------------------------

    @property
    def shape(self) -> tuple[int, int]:
        """Return ``(n_rows, n_columns)``."""
        return (len(self.rows), len(self.columns))

    def _index(self, column: str) -> int:
        try:
            return self.columns.index(column)
        except ValueError as exc:
            raise KeyError(column) from exc

    def column(self, name: str) -> list[Any]:
        """Return all values of ``name`` as a list."""
        index = self._index(name)
        return [row[index] for row in self.rows]

    def column_index(self, name: str) -> int:
        return self._index(name)

    def to_dicts(self) -> list[dict[str, Any]]:
        """Return rows as a list of ``{column: value}`` dicts."""
        return [dict(zip(self.columns, row)) for row in self.rows]

    def add_column(self, name: str, values: Sequence[Any]) -> None:
        """Append a new column. ``values`` must match the row count."""
        if name in self.columns:
            raise ValueError(f"column {name!r} already exists")
        if len(values) != len(self.rows):
            raise ValueError(
                f"expected {len(self.rows)} values, got {len(values)}"
            )
        self.columns.append(name)
        for row, value in zip(self.rows, values):
            row.append(value)

    def remove_column(self, name: str) -> None:
        """Drop a column in place."""
        index = self._index(name)
        del self.columns[index]
        for row in self.rows:
            del row[index]

    def rename_column(self, old: str, new: str) -> None:
        """Rename a column in place."""
        if new in self.columns and new != old:
            raise ValueError(f"column {new!r} already exists")
        self.columns[self._index(old)] = new

    # -- row operations -------------------------------------------------------

    def head(self, n: int = 5) -> "Table":
        """Return a new table with the first ``n`` rows."""
        return Table(self.columns, self.rows[:n])

    def tail(self, n: int = 5) -> "Table":
        """Return a new table with the last ``n`` rows."""
        return Table(self.columns, self.rows[-n:] if n else [])

    def select(self, columns: Sequence[str]) -> "Table":
        """Return a new table containing only ``columns``."""
        indices = [self._index(name) for name in columns]
        rows = [[row[i] for i in indices] for row in self.rows]
        return Table(columns, rows)

    def filter(
        self, predicate: Callable[[dict[str, Any]], bool]
    ) -> "Table":
        """Return rows for which ``predicate(row_dict)`` is true."""
        kept = [row for row in self.to_dicts() if predicate(row)]
        return Table(self.columns, [list(r.values()) for r in kept])

    def sort_by(self, column: str, reverse: bool = False) -> "Table":
        """Return a new table sorted by ``column`` (nulls last)."""
        index = self._index(column)

        def key(row: list[Any]) -> tuple[bool, Any]:
            value = row[index]
            return (value is None, value)

        try:
            rows = sorted(self.rows, key=key, reverse=reverse)
        except TypeError as exc:
            raise TypeError(
                f"cannot sort by {column!r}: mixed value types"
            ) from exc
        return Table(self.columns, rows)

"""Load delimited text (CSV) into a :class:`~tabular.table.Table`."""

from __future__ import annotations

import csv
import io
import os
from typing import Any, Iterable, Sequence

from .table import Table

_MISSING = {"", "na", "n/a", "nan", "null", "none", "-"}


def _open_stream(source: Any, encoding: str):
    """Return a text stream for a path or file-like object."""
    if isinstance(source, (str, os.PathLike)):
        return open(source, "r", encoding=encoding, newline="")
    if isinstance(source, io.TextIOBase):
        return source
    if isinstance(source, io.IOBase) or hasattr(source, "read"):
        return io.TextIOWrapper(source, encoding=encoding, newline="")
    raise TypeError(f"unsupported source type: {type(source)!r}")


def infer_type(value: str) -> Any:
    """Best-effort scalar conversion for a raw CSV field.

    Empty/known-null strings become ``None``. Values that look like integers
    (including negatives) become ``int``; decimals/scientific notation become
    ``float``; everything else stays ``str``. Leading-zero codes such as zip
    codes are preserved as strings.
    """
    text = value.strip()
    if text.lower() in _MISSING:
        return None
    try:
        if text.lstrip("+-").isdigit():
            if len(text.lstrip("+-")) > 1 and text.lstrip("+-").startswith("0"):
                return text
            return int(text)
    except ValueError:
        pass
    try:
        return float(text)
    except ValueError:
        return text


def _infer_column(values: list[str]) -> list[Any]:
    converted = [infer_type(v) for v in values]
    # Only keep numeric conversion if *all* non-missing cells converted.
    non_missing = [v for v in converted if v is not None]
    if non_missing and not all(
        isinstance(v, (int, float)) and not isinstance(v, bool)
        for v in non_missing
    ):
        return [None if v is None else str(v).strip() for v in values]
    return converted


def _normalize_headers(headers: Sequence[str]) -> list[str]:
    seen: dict[str, int] = {}
    result: list[str] = []
    for i, raw in enumerate(headers):
        name = raw.strip() or f"column_{i + 1}"
        if name in seen:
            seen[name] += 1
            name = f"{name}_{seen[name]}"
        else:
            seen[name] = 0
        result.append(name)
    return result


def load_csv(
    source: Any,
    *,
    delimiter: str = ",",
    encoding: str = "utf-8-sig",
    has_header: bool = True,
    infer_types: bool = True,
    skip_blank_lines: bool = True,
) -> Table:
    """Load a CSV file (path or file-like) into a :class:`Table`.

    Args:
        source: Filesystem path or readable text/binary stream.
        delimiter: Field separator, e.g. ``\\t`` for TSV.
        encoding: Text encoding used when ``source`` is a path/binary stream.
        has_header: Treat the first row as column names. When ``False``,
            columns are named ``column_1``..``column_n``.
        infer_types: Convert numeric/null-looking fields to ``int``/``float``
            /``None``. When ``False`` every cell stays a ``str``.
        skip_blank_lines: Ignore fully empty lines.
    """
    stream = _open_stream(source, encoding)
    close = stream is not source and not isinstance(source, io.TextIOBase)
    try:
        reader = csv.reader(stream, delimiter=delimiter)
        records = [row for row in reader if row or not skip_blank_lines]
    finally:
        if close:
            stream.close()

    if not records:
        return Table([])

    if has_header:
        columns = _normalize_headers(records[0])
        data = records[1:]
    else:
        width = max(len(r) for r in records)
        columns = [f"column_{i + 1}" for i in range(width)]
        data = records

    width = len(columns)
    padded: list[list[str]] = []
    for row in data:
        if len(row) < width:
            row = row + [""] * (width - len(row))
        elif len(row) > width:
            row = row[:width]
        padded.append([cell.strip() for cell in row])

    if infer_types:
        matrix = [
            _infer_column([row[i] for row in padded]) for i in range(width)
        ]
        rows = [[matrix[i][r] for i in range(width)] for r in range(len(padded))]
    else:
        rows = padded

    return Table(columns, rows)


def load_rows(
    records: Iterable[dict[str, Any]], columns: Sequence[str] | None = None
) -> Table:
    """Build a :class:`Table` from an iterable of mappings (e.g. sqlite rows)."""
    records = list(records)
    if columns is None:
        columns = list(records[0].keys()) if records else []
    rows = [[record.get(name) for name in columns] for record in records]
    return Table(columns, rows)

"""Cleaning and normalization operations for :class:`~tabular.table.Table`.

Every function returns a new :class:`Table`; inputs are never mutated.
"""

from __future__ import annotations

from typing import Any, Callable, Mapping, Sequence

from .table import Table


def normalize_headers(table: Table, *, lower: bool = False) -> Table:
    """Trim headers and replace internal whitespace with underscores.

    Optionally lowercases names. Name collisions get a numeric suffix.
    """
    result = table.copy()
    seen: dict[str, int] = {}
    for i, raw in enumerate(result.columns):
        name = "_".join(raw.strip().split())
        if lower:
            name = name.lower()
        name = name or f"column_{i + 1}"
        if name in seen:
            seen[name] += 1
            name = f"{name}_{seen[name]}"
        else:
            seen[name] = 0
        result.columns[i] = name
    return result


def strip_whitespace(table: Table) -> Table:
    """Strip leading/trailing whitespace from every string cell."""
    result = table.copy()
    result.rows = [
        [cell.strip() if isinstance(cell, str) else cell for cell in row]
        for row in result.rows
    ]
    return result


def replace_values(
    table: Table,
    column: str,
    mapping: Mapping[Any, Any],
    *,
    regex: bool = False,
) -> Table:
    """Replace values in ``column`` using ``mapping``.

    With ``regex=True`` the keys are treated as regular expression patterns.
    """
    import re

    result = table.copy()
    index = result._index(column)
    if regex:
        compiled = [(re.compile(k), v) for k, v in mapping.items()]
        for row in result.rows:
            value = row[index]
            if isinstance(value, str):
                for pattern, replacement in compiled:
                    value = pattern.sub(str(replacement), value)
                row[index] = value
    else:
        for row in result.rows:
            if row[index] in mapping:
                row[index] = mapping[row[index]]
    return result


def fill_missing(
    table: Table,
    value: Any = None,
    *,
    column: str | None = None,
    method: str | None = None,
) -> Table:
    """Fill ``None`` cells.

    ``value`` may be a scalar or a callable receiving the column name. When
    ``method`` is ``"mean"``/``"median"``/``"mode"`` the fill uses that
    statistic of the column (numeric methods require numeric data).
    """
    result = table.copy()
    targets = [column] if column else list(result.columns)
    for name in targets:
        index = result._index(name)
        values = [row[index] for row in result.rows]
        if method is not None:
            present = [v for v in values if v is not None]
            if method == "mean":
                fill = sum(present) / len(present) if present else None
            elif method == "median":
                fill = _median(present)
            elif method == "mode":
                fill = max(set(present), key=present.count) if present else None
            else:
                raise ValueError(f"unknown fill method: {method!r}")
        elif callable(value):
            fill = value(name)
        else:
            fill = value
        for row in result.rows:
            if row[index] is None:
                row[index] = fill
    return result


def _median(values: Sequence[float]) -> float | None:
    ordered = sorted(values)
    n = len(ordered)
    if n == 0:
        return None
    mid = n // 2
    if n % 2:
        return ordered[mid]
    return (ordered[mid - 1] + ordered[mid]) / 2


def drop_missing(
    table: Table,
    *,
    subset: Sequence[str] | None = None,
    how: str = "any",
) -> Table:
    """Drop rows containing missing values.

    ``how="any"`` removes a row if any selected cell is missing; ``how="all"``
    removes it only when every selected cell is missing.
    """
    if how not in ("any", "all"):
        raise ValueError("how must be 'any' or 'all'")
    columns = list(subset) if subset else list(table.columns)
    indices = [table._index(name) for name in columns]
    kept = []
    for row in table.rows:
        missing = [row[i] is None for i in indices]
        drop = any(missing) if how == "any" else all(missing)
        if not drop:
            kept.append(list(row))
    return Table(table.columns, kept)


def drop_empty_rows(table: Table) -> Table:
    """Drop rows where every cell is ``None`` or an empty string."""
    kept = [
        list(row)
        for row in table.rows
        if any(cell not in (None, "") for cell in row)
    ]
    return Table(table.columns, kept)


def drop_empty_columns(table: Table) -> Table:
    """Drop columns where every cell is ``None`` or an empty string."""
    keep = [
        i
        for i in range(len(table.columns))
        if any(
            row[i] not in (None, "")
            for row in table.rows
        )
    ]
    columns = [table.columns[i] for i in keep]
    rows = [[row[i] for i in keep] for row in table.rows]
    return Table(columns, rows)


def drop_duplicates(
    table: Table, *, subset: Sequence[str] | None = None
) -> Table:
    """Remove duplicate rows, keeping the first occurrence."""
    columns = list(subset) if subset else list(table.columns)
    indices = [table._index(name) for name in columns]
    seen: set[tuple[Any, ...]] = set()
    kept = []
    for row in table.rows:
        key = tuple(row[i] for i in indices)
        if key in seen:
            continue
        seen.add(key)
        kept.append(list(row))
    return Table(table.columns, kept)


def cast_column(
    table: Table, column: str, caster: Callable[[Any], Any]
) -> Table:
    """Apply ``caster`` to every cell in ``column`` (errors propagate)."""
    result = table.copy()
    index = result._index(column)
    for row in result.rows:
        if row[index] is not None:
            row[index] = caster(row[index])
    return result


def coerce_column(
    table: Table,
    column: str,
    caster: Callable[[Any], Any],
    *,
    on_error: Any = None,
) -> Table:
    """Like :func:`cast_column` but replaces failures with ``on_error``."""
    result = table.copy()
    index = result._index(column)
    for row in result.rows:
        if row[index] is None:
            continue
        try:
            row[index] = caster(row[index])
        except (TypeError, ValueError):
            row[index] = on_error
    return result


def rename_columns(table: Table, mapping: Mapping[str, str]) -> Table:
    """Return a copy with columns renamed per ``mapping``."""
    result = table.copy()
    for old, new in mapping.items():
        result.rename_column(old, new)
    return result

"""Descriptive statistics and aggregation for :class:`~tabular.table.Table`."""

from __future__ import annotations

import math
from collections import Counter
from dataclasses import asdict, dataclass, field
from typing import Any, Callable, Mapping, Sequence

from .table import Table

Numeric = (int, float)


def _numeric(values: Sequence[Any]) -> list[float]:
    return [
        float(v)
        for v in values
        if isinstance(v, Numeric) and not isinstance(v, bool)
    ]


@dataclass
class ColumnStats:
    """Summary statistics for a single column."""

    name: str
    dtype: str
    count: int
    missing: int
    unique: int
    min: Any = None
    max: Any = None
    mean: float | None = None
    median: float | None = None
    stdev: float | None = None

    def as_dict(self) -> dict[str, Any]:
        return asdict(self)


def column_type(values: Sequence[Any]) -> str:
    """Return a coarse type label for a sequence of cells.

    One of ``"empty"``, ``"int"``, ``"float"``, ``"bool"`` or ``"str"``.
    """
    present = [v for v in values if v is not None]
    if not present:
        return "empty"
    if all(isinstance(v, bool) for v in present):
        return "bool"
    if all(isinstance(v, int) and not isinstance(v, bool) for v in present):
        return "int"
    if all(isinstance(v, Numeric) and not isinstance(v, bool) for v in present):
        return "float"
    return "str"


def column_types(table: Table) -> dict[str, str]:
    """Map each column name to its inferred type label."""
    return {name: column_type(table.column(name)) for name in table.columns}


def _median(values: list[float]) -> float | None:
    ordered = sorted(values)
    n = len(ordered)
    if n == 0:
        return None
    mid = n // 2
    if n % 2:
        return ordered[mid]
    return (ordered[mid - 1] + ordered[mid]) / 2


def _stdev(values: list[float]) -> float | None:
    n = len(values)
    if n < 2:
        return 0.0 if n == 1 else None
    mean = sum(values) / n
    variance = sum((v - mean) ** 2 for v in values) / (n - 1)
    return math.sqrt(variance)


def describe(table: Table) -> dict[str, ColumnStats]:
    """Return :class:`ColumnStats` keyed by column name for every column."""
    report: dict[str, ColumnStats] = {}
    for name in table.columns:
        values = table.column(name)
        present = [v for v in values if v is not None]
        numbers = _numeric(present)
        non_numeric = [v for v in present if not isinstance(v, Numeric)]
        report[name] = ColumnStats(
            name=name,
            dtype=column_type(values),
            count=len(present),
            missing=len(values) - len(present),
            unique=len(set(present)),
            min=min(non_numeric or numbers, default=None),
            max=max(non_numeric or numbers, default=None),
            mean=sum(numbers) / len(numbers) if numbers else None,
            median=_median(numbers),
            stdev=_stdev(numbers),
        )
    return report


def value_counts(
    table: Table, column: str, *, top: int | None = None
) -> dict[Any, int]:
    """Count occurrences of each value in ``column``, most common first."""
    counts = Counter(table.column(column))
    items = counts.most_common(top)
    return dict(items)


def correlation(table: Table, x: str, y: str) -> float | None:
    """Pearson correlation between two numeric columns.

    Returns ``None`` when fewer than two paired values exist or either column
    has zero variance.
    """
    pairs = [
        (a, b)
        for a, b in zip(table.column(x), table.column(y))
        if isinstance(a, Numeric)
        and isinstance(b, Numeric)
        and not isinstance(a, bool)
        and not isinstance(b, bool)
    ]
    if len(pairs) < 2:
        return None
    xs = [float(a) for a, _ in pairs]
    ys = [float(b) for _, b in pairs]
    mx = sum(xs) / len(xs)
    my = sum(ys) / len(ys)
    cov = sum((a - mx) * (b - my) for a, b in zip(xs, ys))
    var_x = sum((a - mx) ** 2 for a in xs)
    var_y = sum((b - my) ** 2 for b in ys)
    if var_x == 0 or var_y == 0:
        return None
    return cov / math.sqrt(var_x * var_y)


def group_by(table: Table, key: str) -> dict[Any, Table]:
    """Partition rows by the value of ``key``, returning ``{value: Table}``."""
    index = table._index(key)
    buckets: dict[Any, list[list[Any]]] = {}
    for row in table.rows:
        buckets.setdefault(row[index], []).append(list(row))
    return {value: Table(table.columns, rows) for value, rows in buckets.items()}


def aggregate(
    table: Table,
    key: str,
    aggregations: Mapping[str, tuple[str, Callable[[Sequence[Any]], Any]]],
) -> Table:
    """Group by ``key`` and compute aggregates.

    ``aggregations`` maps an output column name to a ``(source_column, func)``
    pair, where ``func`` receives the list of values for that group.
    """
    groups = group_by(table, key)
    columns = [key] + list(aggregations)
    rows: list[list[Any]] = []
    for value, group in groups.items():
        row: list[Any] = [value]
        for source, func in aggregations.values():
            row.append(func(group.column(source)))
        rows.append(row)
    return Table(columns, rows)

